133	// walkLocalStorage returns the recursive size of dir in bytes.
134	// Symlinks are not followed; per-entry errors below the root are ignored
135	// (the walk continues). An error accessing the root itself is returned.
136	func walkLocalStorage(dir string) (int64, error) {
137		if dir == "" {
138			return -1, errors.New("empty data directory")
139		}
140		var total int64
141		err := filepath.WalkDir(dir, func(path string, entry os.DirEntry, walkErr error) error {
142			if walkErr != nil {
143				if path == dir {
144					// Root itself is inaccessible — abort the walk.
145					return walkErr
146				}
147				// Ignore per-entry errors (e.g. permission denied on a single file).
148				return nil
149			}
150			if entry.IsDir() {
151				return nil
152			}
153			info, err := entry.Info()
154			if err != nil {
155				// Ignore stat errors on individual entries; continue the walk.
156				return nil //nolint:nilerr
157			}
158			total += info.Size()
159			return nil
160		})
161		if err != nil {
162			return -1, errors.Wrap(err, "walk failed")
163		}
164		return total, nil
165	}
